/* Minimal bridge: show already verified fine-arts enrichment in the existing detail dialog. */
(() => {
  'use strict';
  const clean=v=>String(v||'').replace(/\s+/g,' ').trim();
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safe=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)?u.href:'';}catch(_){return'';}};
  function items(list,empty){const xs=(Array.isArray(list)?list:[]).filter(x=>x&&clean(x.title)).slice(0,3);if(!xs.length)return `<p class="activity-empty">${esc(empty)}</p>`;return `<ul class="activity-list compact-list">${xs.map(x=>{const url=safe(x.url),title=esc(clean(x.title)),venue=clean(x.venue),date=clean(x.date||x.year);return `<li><div>${url?`<a target="_blank" rel="noreferrer" href="${esc(url)}">${title}</a>`:`<span>${title}</span>`}${venue?`<small>${esc(venue)}</small>`:''}</div>${date?`<span>${esc(date)}</span>`:''}</li>`;}).join('')}</ul>`;}
  function selectedUnit(){const d=document.querySelector('#detail');if(!d?.open)return null;const heading=clean(d.querySelector('.detail-head h2')?.textContent);const name=(heading.match(/^(.+?)\s*교수\s*\//)||[])[1];if(!name)return null;const units=[...(window.RESEARCH_UNITS||[]),...(window.RESEARCH_UNIT_SUPPLEMENTS||[])];return units.find(x=>clean(x.name)===clean(name)&&/미술대학/.test(clean(x.college)))||null;}
  function apply(){const d=document.querySelector('#detail');if(!d?.open)return;const old=d.querySelector('.fine-arts-official-bridge');if(old)old.remove();const x=selectedUnit();if(!x)return;const e=(window.PRECOMPUTED_ENRICHMENT||{})[x.id]||{};if(!(e.recent_solo_exhibitions?.length||e.recent_group_exhibitions?.length||clean(e.education_summary)))return;const section=document.createElement('section');section.className='activity-wrap discipline-activity fine_arts fine-arts-official-bridge';section.innerHTML=`<div class="activity-title"><div><h3>예술 활동</h3><p>서울대학교 미술대학 공식 교수 페이지에서 확인된 최신 활동을 최대 3건씩 보여줍니다.</p></div></div><div class="activity-grid"><article class="activity-card"><h4>최근 개인전</h4>${items(e.recent_solo_exhibitions,'공식 출처에서 확인된 개인전이 아직 없습니다.')}</article><article class="activity-card"><h4>최근 단체전</h4>${items(e.recent_group_exhibitions,'공식 출처에서 확인된 단체전이 아직 없습니다.')}</article><article class="activity-card"><h4>전공·교육 활동</h4><p class="activity-ai-text">${esc(clean(e.education_summary||e.research_summary)||'확인된 설명이 없습니다.')}</p></article></div>`;const target=d.querySelector('#detailContent');target?.appendChild(section);}
  let queued=false;new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(()=>{queued=false;apply();});}}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
  apply();
})();
